import Foundation

/// Decides which pasteboard contents may be stored.
public struct PrivacyPolicy: Sendable {
    /// Pasteboard types password managers set to say "don't record this" (nspasteboard.org).
    public static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    public static let defaultExcludedBundleIds: [String] = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.bitwarden.desktop",
    ]

    public var excludedBundleIds: Set<String>
    public var maxBytes: Int

    public init(excludedBundleIds: Set<String> = Set(PrivacyPolicy.defaultExcludedBundleIds), maxBytes: Int = 1_000_000) {
        self.excludedBundleIds = excludedBundleIds
        self.maxBytes = maxBytes
    }

    public func shouldStore(types: [String], bundleId: String?, text: String) -> Bool {
        if types.contains(where: Self.concealedTypes.contains) { return false }
        if let bundleId, excludedBundleIds.contains(bundleId) { return false }
        if text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { return false }
        return text.utf8.count <= maxBytes
    }
}
